export function initNews({view,esc,date}) {
 const $=id=>document.getElementById(id);
 const db=window.supabase && window.ATLAS_SUPABASE ? window.supabase.createClient(window.ATLAS_SUPABASE.url,window.ATLAS_SUPABASE.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storageKey:'convergencia-aura-auth'}}):null;
 if(db) window.auraClient=db;
 const dev = /^dev--atlas-osint\.netlify\.app$/.test(location.hostname)||['dev.atlas.convergenciaaura.cl','localhost','127.0.0.1'].includes(location.hostname);
 let user=null,articles=[],topics=[],counts=new Map(),liked=new Set(),topic='all',limit=20,activeArticle=null,commentLimit=30,loadToken=0;
 const safe=s=>{try{const u=new URL(s);return u.protocol==='https:'?u.href:'#'}catch{return '#'}};
 const script=document.createElement('script');script.src=dev?'/aura-core-dev/aura-google.js':'/aura-core/aura-google.js';script.defer=true;document.head.append(script);
 const hub=document.createElement('script');hub.src='aura-hub-loader.js';hub.defer=true;document.head.append(hub);
 function openAccount(){ $('account-dialog').showModal(); }
 $('account').addEventListener('aura-hub:login',openAccount);$('account').onclick=()=>{if(!window.AuraHub)openAccount();};$('feed-account').onclick=openAccount;
 $('close-account').onclick=()=> $('account-dialog').close();$('close-comments').onclick=()=>{$('comments-dialog').close();activeArticle=null;loadToken++;};$('close-share').onclick=()=>$('share-dialog').close();
 function authChanged(u){user=u&&!u.is_anonymous?u:null; $('account').textContent=user?'Mi cuenta':'Ingresar';$('account-state').textContent=user?'Sesión de Convergencia activa.':'Ingresa con tu cuenta existente para participar.';$('password-form').hidden=!!user;$('logout').hidden=!user;$('account-dialog').querySelector('[data-aura-google]').hidden=!!user;syncSocial();if(activeArticle)loadComments();}
 if(db){db.auth.getSession().then(({data,error})=>{if(error)$('login-status').textContent='No se pudo recuperar tu sesión.';authChanged(data?.session?.user)}); db.auth.onAuthStateChange((_event,session)=>{setTimeout(()=>authChanged(session?.user),0)});}
 $('password-form').onsubmit=async e=>{e.preventDefault();if(!db)return;$('login-status').textContent='Ingresando…';const b=e.target.querySelector('button');b.disabled=true;try{const {error}=await db.auth.signInWithPassword({email:$('login-email').value.trim(),password:$('login-password').value});$('login-status').textContent=error?'No se pudo ingresar. Revisa tus credenciales.':'Sesión iniciada.';if(!error){$('login-password').value='';$('account-dialog').close();}}catch{$('login-status').textContent='No se pudo conectar. Intenta nuevamente.'}finally{b.disabled=false}};
 $('logout').onclick=async()=>{const {error}=await db.auth.signOut({scope:'local'});$('login-status').textContent=error?'No se pudo cerrar la sesión.':'Sesión cerrada.';};
 function canWrite(){if(!dev){$('social-status').textContent='La participación está habilitada solo en Atlas dev.';return false;}if(!db){$('social-status').textContent='La conexión de cuentas no está disponible.';return false;}if(!user){openAccount();return false;}return true;}
 async function syncSocial(){if(!db||!dev||!articles.length)return;try{const uid=user?.id;const [total,mine]=await Promise.all([db.rpc('atlas_dev_news_counts',{article_ids:articles.map(a=>a.id)}),uid?db.from('atlas_dev_news_likes').select('article_id').eq('user_id',uid).in('article_id',articles.map(a=>a.id)):Promise.resolve({data:[],error:null})]);if(total.error||mine.error)throw Error();counts=new Map(total.data.map(r=>[r.article_id,r]));if(user?.id===uid)liked=new Set(mine.data.map(r=>r.article_id));$('social-status').textContent=user?'Participas con tu cuenta de Convergencia.':'Lectura pública · Ingresa para dar like o comentar.';render();}catch{$('social-status').textContent='No se pudieron cargar las interacciones. Actualiza para reintentar.'}}
 function filtered(){const q=$('news-search').value.trim().toLocaleLowerCase(),source=$('news-source').value,cutoff=Date.now()-Number($('news-period').value)*3600000;const rows=articles.filter(a=>(topic==='all'||a.topics.includes(topic))&&(source==='all'||a.source===source)&&Date.parse(a.publishedAt)>=cutoff&&`${a.title} ${a.source}`.toLocaleLowerCase().includes(q));const order=$('news-order').value;return rows.sort((a,b)=>order==='oldest'?a.publishedAt.localeCompare(b.publishedAt):order==='likes'||order==='comments'?Number(counts.get(b.id)?.[order]||0)-Number(counts.get(a.id)?.[order]||0)||b.publishedAt.localeCompare(a.publishedAt):b.publishedAt.localeCompare(a.publishedAt));}
 function render(){const rows=filtered();$('news-feed').innerHTML=rows.slice(0,limit).map(a=>{const c=counts.get(a.id);return `<article class="news-card"><div class="news-byline"><span>${esc(a.source)}</span><time datetime="${esc(a.publishedAt)}">${esc(date(a.publishedAt))}</time></div><h2><a href="${esc(safe(a.url))}" target="_blank" rel="noopener noreferrer">${esc(a.title)}</a></h2><div class="news-tags">${a.topics.map(t=>`<span>${esc(topics.find(x=>x.id===t)?.label||t)}</span>`).join('')}</div><p class="muted">Titular del medio · vía Google News RSS</p><div class="news-actions"><button data-like="${a.id}" aria-pressed="${liked.has(a.id)}">${liked.has(a.id)?'♥':'♡'} <span>${c?c.likes:'—'}</span> Me gusta</button><button data-comments="${a.id}">☏ ${c?c.comments:'—'} Comentar</button><button data-share="${a.id}">↗ Compartir</button><a href="${esc(safe(a.url))}" target="_blank" rel="noopener noreferrer">Leer noticia ↗</a></div></article>`}).join('')||'<div class="empty">No hay noticias para estos filtros. Prueba otro tema, medio o periodo.</div>';$('more-news').hidden=rows.length<=limit;
 $('news-feed').querySelectorAll('[data-like]').forEach(b=>b.onclick=()=>like(b.dataset.like,b));$('news-feed').querySelectorAll('[data-comments]').forEach(b=>b.onclick=()=>openComments(b.dataset.comments));$('news-feed').querySelectorAll('[data-share]').forEach(b=>b.onclick=()=>share(b.dataset.share));}
 async function like(id,b){if(!canWrite())return;b.disabled=true;try{const result=liked.has(id)?await db.from('atlas_dev_news_likes').delete().eq('article_id',id).eq('user_id',user.id):await db.from('atlas_dev_news_likes').insert({article_id:id,user_id:user.id});if(result.error&&result.error.code!=='23505')throw Error();await syncSocial();}catch{$('social-status').textContent='No se pudo guardar tu reacción. Intenta nuevamente.';}finally{b.disabled=false}}
 async function openComments(id){activeArticle=articles.find(a=>a.id===id);commentLimit=30;$('comments-title').textContent=activeArticle.title;$('comment-body').value='';$('comment-status').textContent='';$('comments-dialog').showModal();await loadComments();}
 async function loadComments(){if(!activeArticle)return;const token=++loadToken;const id=activeArticle.id;$('comments-list').textContent='Cargando conversación…';$('comment-form').hidden=!user||!dev;if(!user)$('comment-status').innerHTML='<button id="comment-login">Ingresar para comentar</button>';else $('comment-status').textContent='';$('comment-login')?.addEventListener('click',openAccount);if(!db||!dev){$('comments-list').textContent='Conversación disponible en Atlas dev.';return;}try{const {data,error}=await db.from('atlas_dev_news_comments').select('id,user_id,author_name,body,created_at').eq('article_id',id).order('created_at',{ascending:false}).order('id',{ascending:false}).limit(commentLimit+1);if(error)throw Error();if(token!==loadToken)return;$('more-comments').hidden=data.length<=commentLimit;$('comments-list').innerHTML=data.slice(0,commentLimit).reverse().map(c=>`<article class="comment"><b>${esc(c.author_name)}</b><time>${esc(date(c.created_at))}</time><p>${esc(c.body)}</p>${c.user_id===user?.id?`<button data-delete-comment="${c.id}">Eliminar mi comentario</button>`:''}</article>`).join('')||'<p class="muted">Todavía no hay comentarios. Puedes iniciar la conversación.</p>';$('comments-list').querySelectorAll('[data-delete-comment]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const {error}=await db.from('atlas_dev_news_comments').delete().eq('id',b.dataset.deleteComment).eq('user_id',user.id);if(error)throw Error();await loadComments();await syncSocial();}catch{$('comment-status').textContent='No se pudo eliminar. Intenta nuevamente.';b.disabled=false}});}catch{if(token===loadToken)$('comments-list').textContent='No se pudieron cargar los comentarios. Cierra y vuelve a abrir para reintentar.'}}
 $('more-comments').onclick=()=>{commentLimit+=30;loadComments()};
 $('comment-form').onsubmit=async e=>{e.preventDefault();if(!canWrite()||!activeArticle)return;const body=$('comment-body').value.trim();if(!body)return;const id=activeArticle.id;$('post-comment').disabled=true;try{const {error}=await db.from('atlas_dev_news_comments').insert({article_id:id,user_id:user.id,body});if(error)throw error;if(activeArticle?.id===id){$('comment-body').value='';await loadComments();$('comment-status').textContent='Comentario publicado.';}await syncSocial();}catch(e){$('comment-status').textContent=String(e.message).includes('Espera un minuto')?'Espera un minuto antes de volver a comentar.':'No se pudo publicar. Tu texto se conserva para reintentar.';}finally{$('post-comment').disabled=false}};
 async function share(id){const a=articles.find(x=>x.id===id);try{if(navigator.share){await navigator.share({title:a.title,url:a.url});return;}await navigator.clipboard.writeText(a.url);$('social-status').textContent='Enlace a la noticia copiado.';}catch(e){if(e.name==='AbortError')return;$('share-link').value=a.url;$('share-dialog').showModal();$('share-link').select();}}
 async function refresh(){ $('news-status').textContent='Consultando noticias de ocho temas…';try{const r=await fetch('/.netlify/functions/headlines',{signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error();const d=await r.json();articles=d.articles;topics=d.topics;const old=$('news-source').value;$('news-source').innerHTML='<option value="all">Todos los medios</option>'+[...new Set(articles.map(a=>a.source))].sort().map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');if([...$('news-source').options].some(o=>o.value===old))$('news-source').value=old;$('news-topics').innerHTML=[{id:'all',label:'Todo'},...topics].map(t=>`<button data-topic="${t.id}" aria-pressed="${topic===t.id}" class="${topic===t.id?'active':''}">${esc(t.label)}</button>`).join('');$('news-topics').querySelectorAll('button').forEach(b=>b.onclick=()=>{topic=b.dataset.topic;limit=20;$('news-topics').querySelectorAll('button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});render()});const failed=d.sources.filter(s=>s.status!=='ok');$('news-status').textContent=`${articles.length} titulares · Consulta: ${date(d.updatedAt)}${failed.length?' · No disponibles: '+failed.map(s=>s.label).join(', '):''}. Hasta 25 titulares por tema.`;render();await syncSocial();}catch{$('news-status').textContent='No se pudieron actualizar las noticias. '+(articles.length?'Se conserva la consulta anterior.':'Pulsa Actualizar fuentes para reintentar.');if(!articles.length)render();}}
 ['news-search','news-source','news-period','news-order'].forEach(id=>$(id).addEventListener(id==='news-search'?'input':'change',()=>{limit=20;render()}));$('more-news').onclick=()=>{limit+=20;render()};refresh();return {refresh};
}
